    for x, y, value in grid_values:
        if x == 0 and y == 0:
            # The top-left corner has a maximum sum of the value placed on it
            max_sums[x][y] = value
        elif x > 0 and y > 0:
            # Update the maximum sum for each path based on the values already placed
            max_sums[x][y] = max(max_sums[x - 1][y], max_sums[x][y - 1], max_sums[x - 1][y - 1]) + value
        elif x > 0 and y == 0:
            # Update the maximum sum for the path from the top-left corner to (x, y)
            max_sums[x][y] = max_sums[x - 1][y] + value
        elif x == 0 and y > 0:
            # Update the maximum sum for the path from the top-left corner to (x, y)
            max_sums[x][y] = max_sums[x][y - 1] + value

