def calculate_score(system, points):
    """
    Calculate the score of a series of ping-pong games based on the provided scoring system.

    :param system: The number of points required to win a game (either 11 or 21).
    :param points: A string of 'W' and 'L' characters denoting points won by the player and opponent.
    :return: A list of game scores formatted as "player_score:opponent_score"
    """
    if system not in [11, 21]:
        raise ValueError("Invalid scoring system. Must be 11 or 21.")

    game_scores = []
    player_score = 0
    opponent_score = 0
    is_player_turn = True

    for ch in points:
        if is_player_turn:
            if ch == "W":
                player_score += 1
            else:
                opponent_score += 1
        else:
            if ch == "W":
                opponent_score += 1
            else:
                player_score += 1
        is_player_turn = not is_player_turn

        if player_score - opponent_score >= system or opponent_score - player_score >= system:
            game_scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    if player_score or opponent_score:
        game_scores.append(f"{player_score}:{opponent_score}")

    return game_scores
