def min_remaining_space(V, n, volumes):
    # Initialize a two-dimensional table to store the results of sub-problems
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Fill the table with -1 to indicate that we haven't computed the value for a given sub-problem
    for i in range(V + 1):
        for j in range(n + 1):
            dp[i][j] = -1

    # Base case: when we have only one item, the maximum volume is equal to the volume of that item
    for i in range(V + 1):
        dp[i][1] = volumes[0]

    # Iterate over the remaining items
    for i in range(2, n + 1):
        for j in range(V + 1):
            # If we have not computed the value for this sub-problem before, compute it now
            if dp[j][i - 1] == -1:
                dp[j][i - 1] = max(dp[j - volumes[i - 1]][i - 1], dp[j][i - 1])
            # If we have computed the value for this sub-problem before, we can reuse the result
            dp[j][i] = max(dp[j - volumes[i - 1]][i - 1], dp[j][i - 1])

    # The minimum remaining space is equal to the difference between the total capacity and the maximum volume occupied by the items
    return V - dp[V][n]
